   // In supabase.service.ts or login component
   let loginAttempts = 0;
   const maxAttempts = 5;
   const backoffDelay = (attempt: number) => Math.pow(2, attempt) * 1000;

   async login(email: string, password: string) {
     if (loginAttempts >= maxAttempts) {
       throw new Error(`Too many login attempts. Try again in ${backoffDelay(loginAttempts)/1000}s`);
     }

     try {
       const result = await this.supabase.auth.signInWithPassword({email, password});
       loginAttempts = 0; // Reset on success
       return result;
     } catch (error) {
       loginAttempts++;
       await delay(backoffDelay(loginAttempts));
