Create error message sanitizer service:

   src/app/services/error-message.service.ts:
   ```typescript
   import { Injectable } from '@angular/core';

   @Injectable({ providedIn: 'root' })
   export class ErrorMessageService {
     getSafeMessage(error: any): string {
       const message = error?.message || 'An error occurred';

       // Sanitize database/system information
       const systemPatterns = [
         /relation "([^"]+)" does not exist/g,
         /UNIQUE constraint failed/,
         /database/i,
         /sql:/i,
         /table/i
       ];

       let safe = message;
       systemPatterns.forEach(pattern => {
         safe = safe.replace(pattern, 'database operation');
       });

       // Log actual error for debugging
       if (error?.code || error?.details) {
         console.error('[Detailed Error]', error);
       }

       return safe || 'Operation failed. Please try again.';
     }
   }
   ```

